// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    /** one @ExceptionHandler method: the exception type it declares and a name for the tests */
    record Handler(Class<? extends Throwable> type, String name) {}
    /** a @RestController: its package and its own @ExceptionHandler methods */
    record Controller(String packageName, List<Handler> handlers) {}
    /** a @ControllerAdvice bean: @Order value (null = none), basePackages (null = every controller), handlers */
    record Advice(Integer order, String basePackage, List<Handler> handlers) {}

    static class NotFoundException extends RuntimeException { NotFoundException(String m) { super(m); } }
    static class OrderNotFoundException extends NotFoundException { OrderNotFoundException(long id) { super("order " + id + " not found"); } }
    static class ConflictException extends RuntimeException { ConflictException(String m) { super(m); } }

    /** Given: the handler declared for the CLOSEST superclass of type (ExceptionDepthComparator), or null. */
    static Handler closest(Class<?> type, List<Handler> handlers) {
        for (Class<?> c = type; c != null; c = c.getSuperclass()) {
            for (var h : handlers) if (h.type() == c) return h;
        }
        return null;
    }

    /** The name of the handler Spring MVC invokes for error thrown by controller, or null when none matches. */
    static String resolve(Throwable error, Controller controller, List<Advice> advices) {
        String own = match(error, controller.handlers());
        if (own != null) return own;
        var ordered = new ArrayList<>(advices);   // stable sort: equal orders keep registration order
        ordered.sort(Comparator.comparingInt(a -> a.order() == null ? Integer.MAX_VALUE : a.order()));
        for (var advice : ordered) {
            if (advice.basePackage() != null && !controller.packageName().startsWith(advice.basePackage())) continue;
            String found = match(error, advice.handlers());
            if (found != null) return found;
        }
        return null;
    }

    /** one handler set: the closest type for the exception itself, else the same search on its cause, and so on */
    static String match(Throwable error, List<Handler> handlers) {
        for (Throwable t = error; t != null; t = t.getCause()) {
            Handler h = closest(t.getClass(), handlers);
            if (h != null) return h.name();
        }
        return null;
    }

    static final Controller ORDERS = new Controller("com.shop.orders", List.of());

