// ─────────────────────────────────────────────────────────────────────────
//  03 · 404, 405, 415 or 400★★★
//  concepts: request mapping · method and media-type conditions · type conversion
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    /** a handler mapping, e.g. new Route("GET", "/api/orders/{id}", null); every {variable} binds to a long */
    record Route(String method, String template, String consumes) {}
    record Request(String method, String path, String contentType) {}
    /** status plus detail: the chosen route ("GET /api/orders/{id}") on 200, the allowed methods on 405, else null */
    record Outcome(int status, String detail) {}

    /** The status Spring MVC produces for req, in the order DispatcherServlet checks. */
    static Outcome dispatch(List<Route> routes, Request req) {
        var byPath = routes.stream().filter(r -> pathMatches(r.template(), req.path())).toList();
        if (byPath.isEmpty()) return new Outcome(404, null);
        var byMethod = byPath.stream().filter(r -> r.method().equals(req.method())).toList();
        if (byMethod.isEmpty()) {
            return new Outcome(405, String.join(", ", new TreeSet<>(byPath.stream().map(Route::method).toList())));
        }
        String type = req.contentType() == null ? null : req.contentType().split(";", 2)[0].trim();
        var byMedia = byMethod.stream().filter(r -> r.consumes() == null || r.consumes().equalsIgnoreCase(type)).toList();
        if (byMedia.isEmpty()) return new Outcome(415, null);
        Route best = byMedia.get(0);
        for (var r : byMedia) if (variables(r.template()) < variables(best.template())) best = r;
        String[] t = segments(best.template()), p = segments(req.path());
        for (int i = 0; i < t.length; i++) {
            if (!t[i].startsWith("{")) continue;
            try {
                Long.parseLong(p[i]);
            } catch (NumberFormatException e) {
                return new Outcome(400, null);
            }
        }
        return new Outcome(200, best.method() + " " + best.template());
    }

    static String[] segments(String path) { return path.substring(1).split("/", -1); }

    static long variables(String template) { return Arrays.stream(segments(template)).filter(s -> s.startsWith("{")).count(); }

    static boolean pathMatches(String template, String path) {
        String[] t = segments(template), p = segments(path);
        if (t.length != p.length) return false;
        for (int i = 0; i < t.length; i++) {
            if (t[i].startsWith("{") ? p[i].isEmpty() : !t[i].equals(p[i])) return false;
        }
        return true;
    }

    static final List<Route> ROUTES = List.of(
        new Route("GET", "/api/orders", null),
        new Route("POST", "/api/orders", "application/json"),
        new Route("GET", "/api/orders/{id}", null),
        new Route("GET", "/api/orders/export", null));

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("a known path with the wrong method is 405 with the allowed methods", () -> eq(dispatch(ROUTES, new Request("DELETE", "/api/orders", null)), new Outcome(405, "GET, POST")));
        test("an unknown path is 404", () -> eq(dispatch(ROUTES, new Request("GET", "/api/customers", null)).status(), 404));
        test("a non-numeric id is 400, not 404: Spring matches first and converts later", () -> eq(dispatch(ROUTES, new Request("GET", "/api/orders/abc", null)), new Outcome(400, null)));
        test("a literal route beats a {variable} sibling", () -> eq(dispatch(ROUTES, new Request("GET", "/api/orders/export", null)), new Outcome(200, "GET /api/orders/export")));
        test("the wrong content type is 415; media-type parameters are ignored", () -> eq(
            List.of(dispatch(ROUTES, new Request("POST", "/api/orders", "text/plain")).status(), dispatch(ROUTES, new Request("POST", "/api/orders", "application/json;charset=UTF-8")).status()),
            List.of(415, 200)));
        test("the method is checked before the id is converted (boundary)", () -> eq(dispatch(ROUTES, new Request("DELETE", "/api/orders/abc", null)), new Outcome(405, "GET")));
        test("an id outside the long range is 400", () -> eq(dispatch(ROUTES, new Request("GET", "/api/orders/99999999999999999999", null)).status(), 400));
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

